from collections.abc import Mapping


def normalize_stock_delta(row: Mapping[str, object]) -> dict[str, str | int]:
    if not isinstance(row, Mapping) or set(row) != {"sku", "delta"}:
        raise ValueError("stock delta must contain exactly sku, delta")
    sku = row["sku"]
    if not isinstance(sku, str) or not sku.strip():
        raise ValueError("invalid SKU")
    delta = row["delta"]
    if type(delta) is not int:
        raise ValueError("invalid stock delta")
    return {"sku": sku.strip().upper(), "delta": delta}

