MAX_PAYLOAD_LIMIT = 65536


class FrameError(ValueError):
    pass


def validate_max_payload(value: object) -> int:
    if type(value) is not int or not 0 <= value <= MAX_PAYLOAD_LIMIT:
        raise ValueError("invalid max_payload")
    return value


def parse_frames(buffer: bytes, max_payload: int) -> tuple[list[bytes], bytes]:
    if type(buffer) is not bytes:
        raise TypeError("buffer must be bytes")
    limit = validate_max_payload(max_payload)
    if len(buffer) < 4:
        return [], buffer
    length = int.from_bytes(buffer[:4], "big")
    if length > limit:
        raise FrameError("frame exceeds max_payload")
    end = 4 + length
    if len(buffer) < end:
        return [], buffer
    return [buffer[4:end]], buffer[end:]

