from legacy_frame_parser import FrameError, parse_frames, validate_max_payload


class FrameDecoder:
    def __init__(self, max_payload: int) -> None:
        self.max_payload = validate_max_payload(max_payload)
        self._buffer = b""

    @property
    def buffered_bytes(self) -> int:
        return len(self._buffer)

    def feed(self, chunk: bytes) -> list[bytes]:
        if type(chunk) is not bytes:
            raise TypeError("chunk must be bytes")
        # This starter wrapper loses prior fragments; the hidden tests exercise it.
        self._buffer = chunk
        try:
            frames, self._buffer = parse_frames(self._buffer, self.max_payload)
        except FrameError:
            self._buffer = b""
            raise
        return frames

    def reset(self) -> None:
        self._buffer = b""
